function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function buildJd(o){
  o=o||{};
  var title=String(o.title||'').trim()||'（待填写职位名称）';
  var team=String(o.team||'').trim()||'（待补充团队）';
  var level=String(o.level||'中级').trim()||'中级';
  var location=String(o.location||'').trim()||'（待补充地点）';
  var resp=splitLines(o.resp); if(!resp.length) resp=['（待补充工作职责）'];
  var req=splitLines(o.req); if(!req.length) req=['（待补充任职要求）'];
  var nice=splitLines(o.nice); if(!nice.length) nice=['（无特别加分项）'];
  var ben=splitLines(o.ben); if(!ben.length) ben=['（待补充薪酬福利）'];
  var lines=[];
  lines.push('# 招聘职位：'+title);
  lines.push('');
  lines.push('## 职位概述');
  lines.push('- 团队：'+team);
  lines.push('- 级别：'+level);
  lines.push('- 工作地点：'+location);
  lines.push('');
  lines.push('## 工作职责');
  resp.forEach(function(r){ lines.push('- '+r); });
  lines.push('');
  lines.push('## 任职要求');
  req.forEach(function(r){ lines.push('- '+r); });
  lines.push('');
  lines.push('## 加分项');
  nice.forEach(function(r){ lines.push('- '+r); });
  lines.push('');
  lines.push('## 薪酬与福利');
  ben.forEach(function(r){ lines.push('- '+r); });
  return {title:title, respCount:resp.length, reqCount:req.length, niceCount:nice.length, benCount:ben.length, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, buildJd:buildJd};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.JdForgePure = EXPORTS; }
